"use client"

import { LiquidHero } from "liquidforge"

export function LiquidHeroSection() {
  return (
    <LiquidHero
      object={{ type: "text", value: "SHIP IT" }}
      preset="mercury-3"
      height="100vh"
      blend
    >
      {/* `blend` inverts this against the liquid behind it. No ancestor of this
          section may set a z-index, transform, filter or opacity below 1 — any
          of those isolates the blend group and flattens the text to white. */}
      <h1 style={{ fontSize: "clamp(2.5rem, 9vw, 7rem)", margin: 0, letterSpacing: "-0.03em" }}>
        Your headline goes here
      </h1>
    </LiquidHero>
  )
}
